import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

/**
 * @name SSRF in requests library
 * @description User-controlled input flowing to HTTP request URLs
 * @kind path-problem
 * @problem.severity high
 * @id py/ssrf-requests
 * @tags security
 *        external/cwe/cwe-918
 */

module SsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to requests.get(), requests.post(), etc.
    exists(API::CallNode call |
      // Direct calls like requests.get(url, ...)
      call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "head", "patch"]).getACall()
      and sink = call.getArg(0)  // First argument is the URL
    ) or
    exists(API::CallNode call |
      // requests.request(method, url, ...)
      call = API::moduleImport("requests").getMember("request").getACall()
      and sink = call.getArg(1)  // Second argument is the URL
    ) or
    exists(API::CallNode call |
      // Session methods: session.get(), session.post(), etc.
      call = API::moduleImport("requests").getMember("Session").getASubclass().getMember(["get", "post", "put", "delete", "head", "patch"]).getACall()
      and sink = call.getArg(0)  // First argument is the URL
    ) or
    exists(API::CallNode call |
      // session.request(method, url, ...)
      call = API::moduleImport("requests").getMember("Session").getASubclass().getMember("request").getACall()
      and sink = call.getArg(1)  // Second argument is the URL
    )
  }
}

module SsrfFlow = TaintTracking::Global<SsrfConfig>;
import SsrfFlow::PathGraph

from SsrfFlow::PathNode source, SsrfFlow::PathNode sink
where SsrfFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability: user input flows to HTTP request URL $@.", source.getNode(), "user input"
